import sys

def solve():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return
    n = int(input_data[0])
    A = input_data[1:n+1]

    def is_stable(X):
        def get_cyclic_shifts(s):
            shifts = set()
            length = len(s)
            for i in range(length):
                shifts.add(s[i:] + s[:i])
            return shifts

        memo = {}

        def can_form(target):
            if not target:
                return True
            if target in memo:
                return memo[target]

            for x in X:
                if target.startswith(x):
                    suffix = target[len(x):]
                    if can_form(suffix):
                        memo[target] = True
                        return True

            memo[target] = False
            return False

        max_len = sum(len(x) for x in X)
        if max_len == 0:
            return True

        visited = set()
        queue = []
        for x in X:
            if x not in visited:
                visited.add(x)
                queue.append(x)

        while queue:
            current = queue.pop(0)
            for x in X:
                concat = current + x
                if len(concat) > max_len:
                    continue
                if concat not in visited:
                    visited.add(concat)
                    queue.append(concat)
                else:
                    continue

        for msg in visited:
            k = 0
            temp = msg
            count_parts = 0
            parts = []
            t = msg
            while t:
                found = False
                for x in X:
                    if t.startswith(x):
                        parts.append(x)
                        t = t[len(x):]
                        found = True
                        break
                if not found:
                    break
            if t != '':
                continue
            k = len(parts)

            shifts = get_cyclic_shifts(msg)
            m = 0
            for shift in shifts:
                if can_form(shift):
                    m += 1

            if m != k:
                return False

        return True

    count = 0
    for i in range(n):
        for j in range(i, n):
            sublist = A[i:j+1]
            if is_stable(sublist):
                count += 1

    print(count)

if __name__ == "__main__":
    solve()
